CELL_SRC[15] = r'''PRE_COLOR = "#156082"
OBSERVED_COLOR = "#0E2841"
COUNTERFACTUAL_COLOR = "#E97132"
EVENT_COLOR = "#8B008B"
DONOR_COLOR = "#4EA72E"
TARGET_COLOR = "#FDDC5C"
def describe_donors(fit_info, case, max_listed=6):
    """Return a one-line description of the selected donor pool."""

    pre_dates = case["pre_dates"]

    pairs = sorted(
        zip(fit_info["selected_cols"], fit_info["weights"]),
        key=lambda item: -item[1],
    )

    parts = []

    for col, weight in pairs[:max_listed]:

        block = fit_info["blocks"][col]

        start_date = pre_dates[block["pre_positions"][0]]
        end_date = pre_dates[block["pre_positions"][-1]]

        parts.append(
            f"D{block['donor_id']} "
            f"{start_date:%Y-%m-%d}..{end_date:%Y-%m-%d} "
            f"w={weight:.3f}"
        )

    if len(pairs) > max_listed:
        parts.append(f"+{len(pairs) - max_listed} more")

    return "   |   ".join(parts)
def donor_reconstruction_over_target(
    site_id, sensor, band, spec, fit_info, case
):
    """
    Rebuild the target window from the selected donors' observed values.

    Each selected donor block contributes its own observed y over its m
    pre-treatment visits. The weighted average of those blocks is what the
    estimator matches to the target window, so plotting it on the observed
    scale shows the pre-treatment fit in the same units as the data.
    """

    obj = series_store[(site_id, sensor, band, spec)]

    pre_lookup = obj["pre_fit"].set_index("date")

    pre_dates = case["pre_dates"]

    m_star = fit_info["m_star"]

    weights = np.asarray(fit_info["weights"], dtype=float)

    target_dates = pre_dates[-m_star:]

    reconstructed = []

    for position in range(m_star):

        donor_values = []

        for col in fit_info["selected_cols"]:

            block = fit_info["blocks"][col]

            donor_date = pre_dates[block["pre_positions"][position]]

            donor_values.append(
                float(pre_lookup.loc[donor_date, "y_star"])
            )

        reconstructed.append(float(np.dot(weights, donor_values)))

    return target_dates, np.asarray(reconstructed, dtype=float)
def plot_case(group_key, fit_info):
    """Draw one figure for a site and sensor, with a panel per band."""

    site_id, sensor, spec = group_key

    case = stack_case_store[group_key]

    bands = fit_info["band_order"]

    m_star = fit_info["m_star"]

    pre_dates = case["pre_dates"]

    # The target window: the final m* pre-treatment visits.
    target_dates = pre_dates[-m_star:]

    target_start = target_dates[0]
    target_end = target_dates[-1]

    # Selected donor blocks, with their weights.
    donor_spans = []

    for col, weight in zip(fit_info["selected_cols"], fit_info["weights"]):

        block = fit_info["blocks"][col]

        donor_spans.append(
            {
                "donor_id": block["donor_id"],
                "weight": float(weight),
                "pre_start": pre_dates[block["pre_positions"][0]],
                "pre_end": pre_dates[block["pre_positions"][-1]],
                "post_start": pre_dates[block["pseudo_post_positions"][0]],
                "post_end": pre_dates[block["pseudo_post_positions"][-1]],
            }
        )

    max_weight = max(
        (span["weight"] for span in donor_spans),
        default=1.0,
    )

    n_bands = len(bands)

    fig, axes = plt.subplots(
        n_bands,
        1,
        figsize=(14, 2.7 * n_bands),
        sharex=True,
    )

    if n_bands == 1:
        axes = [axes]

    case_effects = daily_effects.loc[
        daily_effects["site_id"].eq(site_id)
        &
        daily_effects["sensor"].eq(sensor)
    ]

    for axis_index, (axis, band) in enumerate(zip(axes, bands)):

        obj = series_store[(site_id, sensor, band, spec)]

        series = obj["series"]

        pre_fit = obj["pre_fit"]

        band_effects = (
            case_effects
            .loc[case_effects["band"].eq(band)]
            .sort_values("date")
        )

        # --- Selected donor blocks ------------------------------------------

        for span in donor_spans:

            alpha = 0.10 + 0.35 * (span["weight"] / max_weight)

            axis.axvspan(
                span["pre_start"],
                span["pre_end"],
                color=DONOR_COLOR,
                alpha=alpha,
                linewidth=0,
                zorder=0,
            )

        # --- Target window --------------------------------------------------

        axis.axvspan(
            target_start,
            target_end,
            color=TARGET_COLOR,
            alpha=0.45,
            linewidth=0,
            zorder=0,
        )

        # --- Observed ---------------------------------------------------------

        axis.plot(
            series["date"],
            series["y"],
            color=OBSERVED_COLOR,
            linewidth=0.8,
            marker="o",
            markersize=2.0,
            alpha=0.65,
            zorder=2,
            label="Observed",
        )

        # --- Donor reconstruction over the target window ---------------------
        #
        # The weighted average of the selected donor blocks' observed values,
        # plotted on the target window it was fitted to. No smoothing line is
        # drawn: this is observed data recombined, against observed data.

        target_dates, reconstructed = donor_reconstruction_over_target(
            site_id, sensor, band, spec, fit_info, case
        )

        axis.plot(
            target_dates,
            reconstructed,
            color=PRE_COLOR,
            linewidth=2.0,
            linestyle="--",
            zorder=4,
            label=(
                "Donor reconstruction of target window, "
                f"m*={m_star}"
            ),
        )

        target_observed = pre_fit.loc[
            pre_fit["date"].between(target_start, target_end),
            "y",
        ].to_numpy(float)

        target_rmse = float(
            np.sqrt(np.mean((target_observed - reconstructed) ** 2))
        )

        # --- Synthetic counterfactual ----------------------------------------

        axis.plot(
            band_effects["date"],
            band_effects["counterfactual_y0"],
            color=COUNTERFACTUAL_COLOR,
            linewidth=2.0,
            linestyle="--",
            zorder=4,
            label="Synthetic counterfactual",
        )

        axis.axvline(
            INTERVENTION_DATE,
            color=EVENT_COLOR,
            linewidth=1.4,
            linestyle=":",
            zorder=3,
        )

        mean_effect = float(band_effects["effect_gamma_hat"].mean())

        axis.set_ylabel(band, fontsize=10)

        axis.set_title(
            f"{band}   mean post effect {mean_effect:+.4f}   "
            f"pre-treatment RMSE on target window {target_rmse:.4f}   "
            f"latent donor-fit MSE {fit_info['final_feature_mse'][band]:.4f}",
            fontsize=9,
            loc="left",
        )

        axis.grid(alpha=0.18)

    # --- Legend, including the shaded regions --------------------------------

    from matplotlib.patches import Patch

    handles, labels = axes[0].get_legend_handles_labels()

    handles = handles + [
        Patch(
            facecolor=TARGET_COLOR,
            alpha=0.45,
            label=f"Target window, final m*={m_star} visits",
        ),
        Patch(
            facecolor=DONOR_COLOR,
            alpha=0.35,
            label=(
                f"Selected donor blocks, J*="
                f"{len(fit_info['selected_cols'])}, shaded by weight"
            ),
        ),
    ]

    labels = labels + [h.get_label() for h in handles[-2:]]

    axes[0].legend(
        handles=handles,
        labels=labels,
        loc="upper left",
        fontsize=8,
        ncol=3,
        frameon=True,
        framealpha=0.92,
    )

    axes[-1].set_xlabel("Date")

    fig.suptitle(
        f"{site_id} — {sensor} — SHC no_lag\n"
        f"m*={m_star} of T0={len(pre_dates)} pre-treatment visits   |   "
        f"J*={len(fit_info['selected_cols'])} donors of "
        f"{len(fit_info['blocks'])} candidate blocks   |   "
        f"n={fit_info['n_post']} post visits   |   "
        f"stacked MSE={fit_info['final_mse']:.4f} "
        f"({fit_info['selection_mode']})",
        fontsize=12,
    )

    # Donor pool listed under the panels, so the weights are readable.
    fig.text(
        0.012,
        -0.012,
        "Selected donor pool:  " + describe_donors(fit_info, case),
        fontsize=8,
        color="#444444",
        ha="left",
    )

    fig.tight_layout(rect=(0, 0.01, 1, 0.96))

    figure_file = (
        FIGURE_DIR /
        f"{sensor}_{site_id}_shc_daily.png"
    )

    fig.savefig(
        figure_file,
        dpi=160,
        bbox_inches="tight",
    )

    plt.close(fig)

    return figure_file
figure_files = []
for group_key, fit_info in final_fit_store.items():

    try:

        figure_files.append(
            plot_case(group_key, fit_info)
        )

    except Exception as exc:

        print(f"{group_key}: plotting failed — {exc}")
print(f"Figures written: {len(figure_files)}")
print(f"Folder: {FIGURE_DIR}")
'''

